92	export function MessageList({
93	  messages,
94	  attachments,
95	  streamingMessageId,
96	  toolActivities,
97	  builds,
98	  exportedCopies,
99	  physicalPrints,
100	  changes,
101	  onRetry,
102	  onToolDecision,
103	  onToolCancel,
104	  dimmed,
105	  printerBlocks = [],
106	  onPrinterAction,
107	  answeredState = true,
108	}: Props) {
109	  const attachmentsById = new Map(attachments.map((attachment) => [attachment.id, attachment]));
110	  const listRef = useRef<HTMLDivElement>(null);
111	  const [followBottom, setFollowBottom] = useState(true);
112	
113	  const handleScroll = () => {
114	    const list = listRef.current;
115	    if (!list) return;
116	    const distanceFromBottom = list.scrollHeight - list.scrollTop - list.clientHeight;
117	    setFollowBottom(distanceFromBottom < 24);
118	  };
119	
120	  useLayoutEffect(() => {
121	    const list = listRef.current;
122	    if (list && followBottom) list.scrollTop = list.scrollHeight;
123	  }, [messages, toolActivities, builds, exportedCopies, physicalPrints, changes, printerBlocks, followBottom]);
124	
125	  const history: ManufacturingHistoryEntry[] = [
126	    ...builds.map((record) => ({ kind: 'build' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
127	    ...exportedCopies.map((record) => ({ kind: 'copy' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
128	    ...physicalPrints.map((record) => ({ kind: 'print' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
129	  ];
130	  const activitiesOf = (messageId: string) => toolActivities.filter((activity) => activity.correlationId === messageId);
131	  const plans = planMembers(toolActivities);
132	  const headline = planHeadline(toolActivities);
133	  // A change follows a message or one of its tool activities; both place it
134	  // after that message's group.
135	  const messageOfItem = new Map<string, string>();
136	  for (const message of messages) {
137	    messageOfItem.set(message.id, message.id);
138	    for (const activity of activitiesOf(message.id)) messageOfItem.set(activity.actionId, message.id);
139	  }
140	  const changesAfter = (messageId: string) => changes.filter((change) => messageOfItem.get(change.afterId) === messageId);
141	  const leadingChanges = changes.filter((change) => !messageOfItem.has(change.afterId));
142	  const historyAfter = (messageId: string) => history.filter((entry) => entry.afterMessageId === messageId);
143	  const printerBlocksAfter = (messageId: string) =>
144	    printerBlocks.filter((block) => block.afterMessageId === messageId).sort((a, b) => a.seq - b.seq);
145	  const printerBlockViews = (messageId: string) =>
