182	            <div key={message.id} className="message-group">
183	              <div className="message note" role="status">
184	                {message.text}
185	              </div>
186	            </div>
187	          );
188	        const bubble = (
189	          <div className={`message ${message.role}`}>
190	            {/* The agent does not speak in a bubble: a 20px action/primary
191	                disc stands beside plain text, as the Figma "Chat Bubble"
192	                component's Agent variant has it. Purely decorative -- the
193	                author is already carried by the role class and by the
194	                bubble the user's turn keeps. */}
195	            {message.role === 'assistant' && <span className="agent-avatar" aria-hidden="true" />}
196	            <div className="message-content">
197	              {message.text &&
198	                (message.role === 'assistant' ? (
199	                  <MarkdownMessage streaming={message.id === streamingMessageId}>{message.text}</MarkdownMessage>
200	                ) : (
201	                  <span>{message.text}</span>
202	                ))}
203	              {message.attachments && message.attachments.length > 0 && (
204	                <div className="message-attachments">
205	                  {message.attachments.map((id) => {
206	                    const attachment = attachmentsById.get(id);
207	                    return attachment ? <AttachmentChip key={id} attachment={attachment} /> : null;
208	                  })}
209	                </div>
210	              )}
211	              {message.state === 'failed' && message.error && (
212	                <div className="error">
213	                  {message.error.message}
214	                  {message.error.retryable && (
215	                    <div>
216	                      <button onClick={() => onRetry(message.id)}>Retry</button>
217	                    </div>
218	                  )}
219	                </div>
220	              )}
221	              {message.state === 'stopped' && <div className="meta">Stopped</div>}
222	            </div>
223	          </div>
224	        );
225	        // The message group is one thread item: the turn and the tool cards
226	        // it proposed, 8 apart. What follows it -- change runs and history
227	        // entries -- are thread items of their own.
228	        return (
229	          <Fragment key={message.id}>
230	            <div className="message-group">
231	              {answeredWithoutChange(message) ? (
232	                <div className="answered-turn">
233	                  {bubble}
234	                  <div className="answered-state">Answered · nothing changed</div>
235	                </div>
236	              ) : (
237	                bubble
238	              )}
239	              {activitiesOf(message.id).map((activity) => {
240	                const key = planKey(activity);
241	                const found = key ? plans.get(key) : undefined;
242	                // A plan of one change is decided like any other call, once
243	                // the agent can no longer add to it.
244	                const members = found && (found.length > 1 || streamingMessageId !== null) ? found : undefined;
245	                if (members && members[0].actionId !== activity.actionId) return null;
246	                return members ? (
247	                  <PlanActivityCard
248	                    key={activity.actionId}
249	                    members={members}
250	                    headline={headline}
251	                    stillProposing={streamingMessageId !== null}
252	                    onDecision={onToolDecision}
253	                    onCancel={onToolCancel}
254	                  />
255	                ) : (
256	                  <ToolActivityCard
257	                    key={activity.actionId}
258	                    activity={activity}
259	                    onDecision={onToolDecision}
260	                    onCancel={onToolCancel}
261	                  />
262	                );
263	              })}
264	            </div>
265	            {printerBlockViews(message.id)}
266	            <TimelineBlocks blocks={timeline(historyAfter(message.id), changesAfter(message.id))} />
267	          </Fragment>
268	        );
269	      })}
270	    </div>
271	  );
272	}
