1	// The page in printer-panel mode: the same thread and composer as the docked
2	// panel, with the printer session's header, pinned card and chips around
3	// them. What it sends back is a typed printer action or an ordinary message.
4	
5	import { act, render, screen } from '@testing-library/react';
6	import userEvent from '@testing-library/user-event';
7	import { beforeEach, describe, expect, it } from 'vitest';
8	import { App } from './App';
9	import { PROTOCOL_NAME, PROTOCOL_VERSION } from './bridge/protocol';
10	import type { Envelope, PrinterSessionPayload, StatePayload, WorkspaceContext } from './bridge/protocol';
11	
12	const context: WorkspaceContext = {
13	  sessionId: '1',
14	  revision: 1,
15	  projectName: 'Garage bracket',
16	  printer: { preset: 'Bambu Lab A1 mini 0.4 nozzle', process: 'Standard', plateType: 'Textured PEI Plate' },
17	  filaments: [],
18	  plates: [],
19	  presetDeltas: [],
20	} as unknown as WorkspaceContext;
21	
22	class MockHost {
23	  received: Envelope[] = [];
24	
25	  transport = {
26	    post: (json: string) => {
27	      this.received.push(JSON.parse(json));
28	    },
29	  };
30	
31	  deliver(type: string, payload: unknown): void {
32	    act(() => {
33	      window.__jusprinBridge!.deliver({
34	        protocol: PROTOCOL_NAME,
35	        version: PROTOCOL_VERSION,
36	        id: `h-${this.received.length}-${type}`,
37	        type,
38	        payload,
39	      } as Envelope);
40	    });
41	  }
42	
43	  lastOfType(type: string): Envelope | undefined {
44	    return [...this.received].reverse().find((envelope) => envelope.type === type);
45	  }
46	}
47	
48	function session(overrides: Partial<PrinterSessionPayload> = {}): PrinterSessionPayload {
49	  return {
50	    mode: 'add',
51	    caption: 'NEW PRINTER',
52	    facts: {
53	      printer: { value: 'Bambu Lab A1 mini', provenance: 'settled' },
54	      nozzle: { value: '0.4 mm', provenance: 'assumed' },
55	      plate: { value: 'Textured PEI Plate', provenance: 'assumed' },
56	      filament: { value: 'PLA', provenance: 'assumed' },
57	    },
58	    blocks: [],
59	    chips: [{ id: 'add', label: 'Add this printer', style: 'primary', action: 'add' }],
60	    chipHint: '',
61	    placeholder: 'e.g. "I put a 0.6 nozzle on it"',
62	    ...overrides,
63	  };
64	}
65	
66	function state(overrides: Partial<StatePayload> = {}): StatePayload {
67	  return {
68	    agent: { status: 'ready' },
69	    appearance: 'light',
70	    conversations: [{ id: 'conv-1', title: 'Printer', createdAt: 't' }],
71	    activeConversationId: 'conv-1',
72	    conversation: [{ id: 'm-1', role: 'assistant', state: 'complete', text: 'What printer do you have?', seq: 1 }],
73	    streamingMessageId: null,
74	    toolActivities: [],
75	    builds: [],
76	    exportedCopies: [],
77	    physicalPrints: [],
78	    draft: '',
79	    context,
80	    session: session(),
81	    ...overrides,
82	  } as unknown as StatePayload;
83	}
84	
85	function open(payload: StatePayload = state()): MockHost {
86	  const host = new MockHost();
87	  render(<App getTransport={() => host.transport} printerPanel />);
88	  host.deliver('hello_ack', { version: PROTOCOL_VERSION });
89	  host.deliver('state', payload);
90	  return host;
91	}
92	
93	describe('the printer panel page', () => {
94	  beforeEach(() => {
95	    document.body.innerHTML = '';
96	  });
97	
98	  it('names where back leads, not the printer it is about', async () => {
